node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Actor_QueueActionMoveToBone(so_activator, so_self, "player-snap");
	Actor_QueueActionSendCommandWord(so_activator, so_self, "activate");
	Actor_QueueActionWaitForCommandWord(so_activator, "activate");
	Actor_QueueActionPlayAnimation(so_activator, "climb_down_shelter", true);

	Actor_QueueActionWaitForCommandWord(so_self, "activate");
	local open = StageObject_GetKeyValue(so_self, "open", false);
	if (!open)
		Actor_QueueActionPlayAnimation(so_self, "open", true);
	Actor_QueueActionSendCommandWord(so_self, so_activator, "activate");
}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Actor_QueueActionSetVisible(so_activator, false);
	Actor_QueueActionSnapToBone(so_activator, so_self, "player-snap");
	Actor_QueueActionWait(so_activator, 1.5);
	Actor_QueueActionSetVisible(so_activator, true);
	Actor_QueueActionPlayAnimation(so_activator, "climb_up_shelter", true);

	Actor_QueueActionPlayAnimation(so_self, "open", true);
}

node.interaction_2_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local script_cinema_on = @"Game_SetCinemaMode(true);";
	local script_cinema_off = @"Game_SetCinemaMode(false);";
	Actor_QueueActionSetVisible(so_activator, false);
	Actor_QueueActionRunScript(so_activator, script_cinema_on);
	Actor_QueueActionSnapToBone(so_activator, so_self, "player-snap");
	Actor_QueueActionWait(so_activator, 0.5);
	Actor_QueueActionSetVisible(so_activator, true);
	Actor_QueueActionPlayAnimation(so_activator, "climb_up_shelter", true);
	Actor_QueueActionRunScript(so_activator, script_cinema_off);

	Actor_QueueActionPlayAnimation(so_self, "open", true);
	Actor_QueueActionWait(so_self, 3.0);
	Actor_QueueActionPlayAnimation(so_self, "close", true);
}

node.interaction_3_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{
	local monsters_inside = StageObject_GetKeyValue(so_self, "monsters_inside");
	local cleared = StageObject_GetKeyValue(so_self, "cleared");
	return !Game_IsShowingActorNotification(so_self) && monsters_inside && !cleared;
}

node.interaction_3_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_SetRecipeUnlocked("BUILDER", true, true);
	Game_AddActorNotification(so_activator, LOC_TEXT("I can hear monsters inside. I should lure them out before entering. [EMOJI=thinking face]"));
//    Game_AddActorNotification(so_activator, LOC_TEXT("I better build some defences before doing that."));
}

node.interaction_4_script_to_test_if_interact:
function IsInteractionAvailable(so_self, so_activator)
{
	local cleared = StageObject_GetKeyValue(so_self, "cleared");
	return !Game_IsShowingActorNotification(so_self) && cleared;
}

node.interaction_4_script_to_run_on_interacti:
function GetLoudspeaker(so_self)
{
	local pos = StageObject_GetStagePosition(so_self);
	local at = "actors/interactives/evac-shelter-loudspeaker.xml";
	local loudspeaker = Stage_QueryNearestActorWithType(pos[0], pos[1], pos[2], 2*20*60, at);
	return loudspeaker;
}

function OnInteraction(so_self, so_activator)
{
	Game_SetCinemaMode(true);

	local open = StageObject_GetKeyValue(so_self, "open", false);
	if (!open)
		Actor_QueueActionPlayAnimation(so_self, "open", false);

	Game_SetStagePointOfInterestCompleted(so_self);

	Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", false);
	Actor_QueueActionMoveToBone(so_activator, so_self, "player-snap");
	Actor_QueueActionSendCommandWord(so_activator, so_self, "activate");
	Actor_QueueActionWaitForCommandWord(so_activator, "activate");

	local script_enter = @"
		Game_SetScreenFadeOutWithCommand(1.5, ""enter_special_stage"", $so_self, 2.25);
	";
	script_enter = string_replace(script_enter, "$so_self", so_self.tostring());

	Actor_QueueActionRunScript(so_activator, script_enter);

	Actor_QueueActionPlayAnimation(so_activator, "climb_down_shelter", true);

	Actor_QueueActionWaitForCommandWord(so_self, "activate");
	Actor_QueueActionSendCommandWord(so_self, so_activator, "activate");

	local so_loud = GetLoudspeaker(so_self);
	local quest_id = "quests/shelter-defence.nut";//StageObject_GetKeyValue(so_loud, "quest_id");

	Game_SendQuestPhaseGoalCommandWord(quest_id, "PHASE_0", "ENTER_SHELTER", "complete");
}

